# Code Generated by Sidekick is for learning and experimentation purposes only.
# filename: fraud_service/app/rules/amount_rules.py

from fraud_service.app.schemas.fraud import RuleResult

RISKY_EMAIL_DOMAINS = {"tempmail.com", "throwaway.email", "mailinator.com", "guerrillamail.com"}


class AmountRules:

    def check_micro_transaction(self, amount: int) -> RuleResult:
        if amount < 100:
            return RuleResult(
                rule_name="micro_transaction",
                triggered=True,
                score_impact=30,
                reason=f"Suspiciously small amount: ${amount/100:.2f}"
            )
        return RuleResult(rule_name="micro_transaction", triggered=False, score_impact=0)

    def check_round_number(self, amount: int) -> RuleResult:
        if amount >= 20000 and amount % 10000 == 0:
            return RuleResult(
                rule_name="round_amount",
                triggered=True,
                score_impact=10,
                reason=f"Round number amount: ${amount/100:.2f}"
            )
        return RuleResult(rule_name="round_amount", triggered=False, score_impact=0)

    def check_high_amount_new_customer(self, amount: int, tx_count: int) -> RuleResult:
        if tx_count == 0 and amount > 50000:
            return RuleResult(
                rule_name="high_amount_new_customer",
                triggered=True,
                score_impact=25,
                reason=f"First transaction of ${amount/100:.2f}"
            )
        return RuleResult(rule_name="high_amount_new_customer", triggered=False, score_impact=0)

    def check_email_domain(self, email: str) -> RuleResult:
        domain = email.split("@")[-1].lower() if "@" in email else ""
        if domain in RISKY_EMAIL_DOMAINS:
            return RuleResult(
                rule_name="risky_email_domain",
                triggered=True,
                score_impact=20,
                reason=f"Disposable email domain: {domain}"
            )
        return RuleResult(rule_name="email_domain", triggered=False, score_impact=0)

    def get_email_domain_risk(self, email: str) -> float:
        domain = email.split("@")[-1].lower() if "@" in email else ""
        return 1.0 if domain in RISKY_EMAIL_DOMAINS else 0.0
